-- ============================================================
-- TEVULY · Cloudflare D1 Edge Schema · migration 0001
--
-- Deterministic and reproducible: D1 tracks applied migrations by
-- idempotent journal entry; this file only ever runs once per DB.
--
-- Conventions
--   * Money        = INTEGER cents (never REAL/FLOAT).
--   * Timestamps   = INTEGER unixepoch() seconds (UTC).
--   * ids          = TEXT, generated by the worker (uuid/cuid).
--   * Booleans     = INTEGER 0/1.
--   * Arrays       = TEXT JSON (images_json / tags_json / badges_json).
--   * FK constraints are declared for documentation; D1 does not
--     enforce them — application logic + indexes guarantee integrity.
--
-- NULL semantics (reviewed)
--   * cart_items.variant_id  NOT NULL — every cart line is bound to a
--     concrete variant; therefore UNIQUE(cart_id, variant_id) is a
--     sound, intentional constraint (see §7 of the directive).
--   * orders.profile_id      NULL allowed  = guest checkout.
--   * compare_at_cents       NULL allowed  = no anchor/strikethrough.
--   * printful_sync_id       NULL allowed  = not yet imported.
--   * rating fields         ARE stored but are only surfaced in SEO
--     JSON-LD when `ratings_verified = 1` — no fabricated reviews.
-- ============================================================

PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = OFF;

-- ------------------------------------------------------------
-- Catalog: categories
-- ------------------------------------------------------------
CREATE TABLE categories (
  id         TEXT PRIMARY KEY,
  slug       TEXT NOT NULL UNIQUE,
  name       TEXT NOT NULL,
  parent_id  TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active  INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

-- ------------------------------------------------------------
-- Catalog: shops (artists/sellers)
-- ------------------------------------------------------------
CREATE TABLE shops (
  id         TEXT PRIMARY KEY,
  slug       TEXT NOT NULL UNIQUE,
  name       TEXT NOT NULL,
  avatar_url TEXT,
  bio        TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

-- ------------------------------------------------------------
-- Catalog: products (TEVULY canonical product)
-- Mirrors the frontend `Product` interface (price_cents, compare_price,
-- images, badges, rating_*, sales_count, free_shipping, ...).
-- ------------------------------------------------------------
CREATE TABLE products (
  id                   TEXT PRIMARY KEY,
  slug                 TEXT NOT NULL UNIQUE,
  title                TEXT NOT NULL,
  description          TEXT NOT NULL DEFAULT '',
  category_id          TEXT NOT NULL,
  shop_id              TEXT NOT NULL,
  price_cents          INTEGER NOT NULL CHECK (price_cents >= 0),
  compare_at_cents     INTEGER CHECK (compare_at_cents IS NULL OR compare_at_cents >= 0),
  images_json          TEXT NOT NULL DEFAULT '[]',
  tags_json            TEXT NOT NULL DEFAULT '[]',
  badges_json          TEXT NOT NULL DEFAULT '[]',

  rating_avg           REAL    NOT NULL DEFAULT 0,
  rating_count         INTEGER NOT NULL DEFAULT 0,
  ratings_verified     INTEGER NOT NULL DEFAULT 0,
  sales_count          INTEGER NOT NULL DEFAULT 0,

  is_featured          INTEGER NOT NULL DEFAULT 0,
  is_trending          INTEGER NOT NULL DEFAULT 0,
  is_eco               INTEGER NOT NULL DEFAULT 0,
  is_made_to_order     INTEGER NOT NULL DEFAULT 0,
  free_shipping        INTEGER NOT NULL DEFAULT 0,
  active               INTEGER NOT NULL DEFAULT 1,
  in_stock             INTEGER NOT NULL DEFAULT 1,

  printful_sync_id     TEXT,

  seo_meta_title       TEXT,
  seo_meta_description TEXT,
  seo_keywords         TEXT,

  created_at           INTEGER NOT NULL,
  updated_at           INTEGER NOT NULL
);

-- Read-path indexes (Phase A access patterns)
CREATE INDEX idx_products_category ON products(category_id) WHERE active = 1;
CREATE INDEX idx_products_shop     ON products(shop_id)     WHERE active = 1;
CREATE INDEX idx_products_featured ON products(is_featured) WHERE active = 1;
CREATE INDEX idx_products_trending ON products(is_trending) WHERE active = 1;
CREATE INDEX idx_products_top      ON products(sales_count DESC) WHERE active = 1;

-- ------------------------------------------------------------
-- Catalog: print_variants (size/color fulfillment units)
-- Mapped to Printful SyncVariant ids. id UNIQUE + product index.
-- ------------------------------------------------------------
CREATE TABLE print_variants (
  id               TEXT PRIMARY KEY,
  product_id       TEXT NOT NULL,
  sync_variant_id  TEXT NOT NULL UNIQUE,
  external_id      TEXT,
  size             TEXT,
  color_name       TEXT,
  color_code       TEXT,
  title            TEXT,
  price_cents      INTEGER NOT NULL CHECK (price_cents >= 0),
  compare_at_cents INTEGER CHECK (compare_at_cents IS NULL OR compare_at_cents >= 0),
  is_available     INTEGER NOT NULL DEFAULT 1,
  stock            INTEGER,
  created_at       INTEGER NOT NULL,
  updated_at       INTEGER NOT NULL
);

CREATE INDEX idx_variants_product ON print_variants(product_id);
CREATE INDEX idx_variants_avail   ON print_variants(product_id, is_available);

-- ------------------------------------------------------------
-- Identity: profiles / addresses
-- ------------------------------------------------------------
CREATE TABLE profiles (
  id             TEXT PRIMARY KEY,
  email          TEXT NOT NULL UNIQUE,
  email_verified INTEGER NOT NULL DEFAULT 0,
  full_name      TEXT,
  avatar_url     TEXT,
  role           TEXT NOT NULL DEFAULT 'customer' CHECK (role IN ('customer', 'artist', 'admin')),
  shop_id        TEXT,
  created_at     INTEGER NOT NULL,
  updated_at     INTEGER NOT NULL
);

CREATE TABLE addresses (
  id           TEXT PRIMARY KEY,
  profile_id   TEXT NOT NULL,
  is_default   INTEGER NOT NULL DEFAULT 0,
  full_name    TEXT NOT NULL,
  line1        TEXT NOT NULL,
  line2        TEXT,
  city         TEXT NOT NULL,
  state        TEXT,
  postal_code  TEXT,
  country_code TEXT NOT NULL,
  phone        TEXT,
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL
);

CREATE INDEX idx_addresses_profile ON addresses(profile_id);

-- ------------------------------------------------------------
-- Commerce: orders (PayPal + Printful correlation, state machine)
-- status: pending -> payment_created -> payment_approved -> paid
--         -> submitted_printful -> shipped -> fulfilled
--         cancelled | refunded | failed
-- Shipping/customer fields are immutable SNAPSHOTS decoupled from
-- later profile/address edits.
-- ------------------------------------------------------------
CREATE TABLE orders (
  id                       TEXT PRIMARY KEY,
  order_number             TEXT NOT NULL UNIQUE,
  profile_id               TEXT,
  guest_email              TEXT,
  status                   TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'payment_created', 'payment_approved', 'paid',
                      'submitted_printful', 'shipped', 'fulfilled',
                      'cancelled', 'refunded', 'failed')),

  currency                 TEXT NOT NULL DEFAULT 'USD',
  subtotal_cents           INTEGER NOT NULL CHECK (subtotal_cents >= 0),
  shipping_cents           INTEGER NOT NULL DEFAULT 0 CHECK (shipping_cents >= 0),
  tax_cents                INTEGER NOT NULL DEFAULT 0 CHECK (tax_cents >= 0),
  discount_cents           INTEGER NOT NULL DEFAULT 0 CHECK (discount_cents >= 0),
  total_cents              INTEGER NOT NULL CHECK (total_cents >= 0),

  paypal_order_id          TEXT,
  paypal_capture_id        TEXT,
  paypal_payer_id          TEXT,
  paypal_transactions_json TEXT NOT NULL DEFAULT '[]',

  printful_order_id        TEXT,
  printful_status          TEXT,
  printful_error           TEXT,

  cart_do_id               TEXT,

  ship_full_name    TEXT NOT NULL,
  ship_line1        TEXT NOT NULL,
  ship_line2        TEXT,
  ship_city         TEXT NOT NULL,
  ship_state        TEXT,
  ship_postal_code  TEXT NOT NULL,
  ship_country_code TEXT NOT NULL,
  ship_phone        TEXT,
  ship_tracking_meta_json TEXT,

  created_at        INTEGER NOT NULL,
  updated_at        INTEGER NOT NULL
);

CREATE INDEX idx_orders_profile  ON orders(profile_id) WHERE profile_id IS NOT NULL;
CREATE INDEX idx_orders_status   ON orders(status);
CREATE INDEX idx_orders_capture  ON orders(paypal_capture_id) WHERE paypal_capture_id IS NOT NULL;
CREATE INDEX idx_orders_printful ON orders(printful_order_id) WHERE printful_order_id IS NOT NULL;

-- ------------------------------------------------------------
-- Commerce: order_items — immutable snapshots
-- ------------------------------------------------------------
CREATE TABLE order_items (
  id               TEXT PRIMARY KEY,
  order_id         TEXT NOT NULL,
  product_id       TEXT NOT NULL,
  variant_id       TEXT,
  sync_variant_id  TEXT NOT NULL,
  title            TEXT NOT NULL,
  variant_label    TEXT,
  unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),
  quantity         INTEGER NOT NULL CHECK (quantity > 0),
  line_total_cents INTEGER NOT NULL CHECK (line_total_cents >= 0)
);

CREATE INDEX idx_order_items_order ON order_items(order_id);

-- ------------------------------------------------------------
-- Integrations: webhook event ledger (hard idempotency)
-- ------------------------------------------------------------
CREATE TABLE webhook_events (
  id           TEXT PRIMARY KEY,
  source       TEXT NOT NULL CHECK (source IN ('paypal', 'printful')),
  event_id     TEXT NOT NULL,
  event_type   TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'received'
    CHECK (status IN ('received', 'processing', 'processed', 'failed')),
  created_at   INTEGER NOT NULL,
  processed_at INTEGER,
  UNIQUE (source, event_id)
);

CREATE INDEX idx_webhook_pending ON webhook_events(status, created_at);

-- ------------------------------------------------------------
-- Async: unified job engine (Free: cron+poller · Paid: Queues)
-- Status transitions: queued -> leased -> done | failed; failed -> leased.
-- ---------------
CREATE TABLE jobs (
  id           TEXT PRIMARY KEY,
  job_type     TEXT NOT NULL CHECK (job_type IN ('catalog_sync', 'fulfill_order', 'send_email')),
  payload_json TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'leased', 'done', 'failed')),
  lease_until  INTEGER,
  attempts     INTEGER NOT NULL DEFAULT 0,
  max_attempts INTEGER NOT NULL DEFAULT 5,
  error        TEXT,
  run_after    INTEGER,
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL,
  completed_at INTEGER
);

CREATE INDEX idx_jobs_pickup ON jobs(status, run_after) WHERE status IN ('queued', 'failed');

-- ------------------------------------------------------------
-- Carts (free-tier stateful cart; version = optimistic lock)
-- ------------------------------------------------------------
CREATE TABLE carts (
  id         TEXT PRIMARY KEY,
  profile_id TEXT,
  currency   TEXT NOT NULL DEFAULT 'USD',
  version    INTEGER NOT NULL DEFAULT 1,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE INDEX idx_carts_expiry ON carts(expires_at);

CREATE TABLE cart_items (
  id               TEXT PRIMARY KEY,
  cart_id          TEXT NOT NULL,
  product_id       TEXT NOT NULL,
  variant_id       TEXT NOT NULL,
  sync_variant_id  TEXT NOT NULL,
  quantity         INTEGER NOT NULL CHECK (quantity > 0),
  unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),
  added_at         INTEGER NOT NULL,
  UNIQUE (cart_id, variant_id)
);

CREATE INDEX idx_cart_items_cart ON cart_items(cart_id);

-- ------------------------------------------------------------
-- updated_at maintenance triggers
-- ------------------------------------------------------------
CREATE TRIGGER trg_products_updated    AFTER UPDATE ON products       BEGIN UPDATE products       SET updated_at = unixepoch() WHERE id = NEW.id; END;
CREATE TRIGGER trg_variants_updated    AFTER UPDATE ON print_variants BEGIN UPDATE print_variants SET updated_at = unixepoch() WHERE id = NEW.id; END;
CREATE TRIGGER trg_shops_updated       AFTER UPDATE ON shops          BEGIN UPDATE shops          SET updated_at = unixepoch() WHERE id = NEW.id; END;
CREATE TRIGGER trg_categories_updated  AFTER UPDATE ON categories     BEGIN UPDATE categories     SET updated_at = unixepoch() WHERE id = NEW.id; END;
CREATE TRIGGER trg_profiles_updated    AFTER UPDATE ON profiles       BEGIN UPDATE profiles       SET updated_at = unixepoch() WHERE id = NEW.id; END;
CREATE TRIGGER trg_addresses_updated   AFTER UPDATE ON addresses      BEGIN UPDATE addresses      SET updated_at = unixepoch() WHERE id = NEW.id; END;
CREATE TRIGGER trg_orders_updated      AFTER UPDATE ON orders         BEGIN UPDATE orders         SET updated_at = unixepoch() WHERE id = NEW.id; END;
CREATE TRIGGER trg_jobs_updated        AFTER UPDATE ON jobs           BEGIN UPDATE jobs           SET updated_at = unixepoch() WHERE id = NEW.id; END;
CREATE TRIGGER trg_carts_updated       AFTER UPDATE ON carts          BEGIN UPDATE carts          SET updated_at = unixepoch() WHERE id = NEW.id; END;
CREATE TRIGGER trg_cart_items_updated  AFTER UPDATE ON cart_items     BEGIN UPDATE cart_items     SET updated_at = unixepoch() WHERE id = NEW.id; END;